parameters.jsCode:
// Exnoria - exp.contact.upgrade
// Branch based on signal_id to handle different upgrade scenarios
// This workflow executes AFTER HITL approval

const webhook = $("Webhook").first().json.body;
const contact = $input.first().json;

const { contact_id, signal_id, signal_severity } = webhook;

const firstname = contact.properties?.firstname?.value ?? 'Contact';
const lastname  = contact.properties?.lastname?.value  ?? '';
const email     = contact.properties?.email?.value     ?? '';

let tags = [];
let whatsappMessage = null;
let taskSubject = null;
let taskPriority = 'MEDIUM';

// Branch based on signal_id
if (signal_id === 'EXP_VAL_01') {
  // Unwilling to pay more - send upgrade prompt with tier comparison
  tags.push('exp-upgrade-initiated');
  whatsappMessage = `Hi ${firstname}, thanks for being a valued customer! We'd love to show you how you can get even more from our platform. Here's a comparison of our tiers: [LINK]`;
} else if (signal_id === 'EXP_VAL_02') {
  // Low ROI perception - co-create business case
  tags.push('exp-roi-case');
  taskSubject = `Co-create ROI business case with ${contact_id}`;
  taskPriority = 'HIGH';
}

return [{
  json: {
    contact_id,
    signal_id,
    signal_severity,
    email,
    firstname,
    lastname,
    tags,
    whatsapp_message: whatsappMessage,
    task_subject: taskSubject,
    task_priority: taskPriority
  }
}];

// Simulate -- WhatsApp message send (only if message exists)
// Replace with real WhatsApp API when ready

const data = $input.first().json;

if (data.whatsapp_message) {
  return [{
    json: {
      ...data,
      message_sent: true,
      simulated: true,
      timestamp: Date.now()
    }
  }];
} else {
  return [{
    json: {
      ...data,
      message_sent: false
    }
  }];
}

